package com.mavric.health.persistence.sqlserver;
import java.util.*;
import java.math.*;
import java.time.*;
import java.util.function.Supplier;
import tools.jackson.databind.ObjectMapper;
import com.mavric.health.inventory.domain.Requests.Lot;
import com.mavric.health.inventory.domain.Requests.Move;
import com.mavric.health.inventory.domain.Requests.Transfer;
import jakarta.servlet.http.HttpServletRequest;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import com.mavric.health.identity.Actor;
import com.mavric.health.tenancy.TenantRef;
import com.mavric.health.shared.*;
/** Explicit inventory adapter, no bean/wiring. Executor and REQUIRED manager must share the future runtime datasource.
 * V6 owns membership/module visibility; no Java branch filtering or stock/prescription rules. */
public final class SqlServerInventoryStore {
 private final SqlServerExecutor executor;private final TransactionTemplate transactions;private final ObjectMapper mapper;
 /** Read/receive compatibility; DTO writes require the configured Spring mapper overload, never a hidden default. */
 public SqlServerInventoryStore(SqlServerExecutor executor,PlatformTransactionManager manager){this(executor,manager,null);}
 public SqlServerInventoryStore(SqlServerExecutor executor,PlatformTransactionManager manager,ObjectMapper mapper){this.executor=Objects.requireNonNull(executor);this.transactions=new TransactionTemplate(Objects.requireNonNull(manager));this.mapper=mapper;}
 private <T>T within(Supplier<T> work){try{return transactions.execute(tx->work.get());}catch(RuntimeException failure){throw SqlServerErrors.map(failure);}}
 private static SqlServerContext context(HttpServletRequest req,String module,Set<String> roles){var c=authority(req,roles);module(req,module);return c;}
 private static SqlServerContext authority(HttpServletRequest req,Set<String> roles){if(req==null)throw SqlServerErrors.database();Object host=req.getAttribute("health.tenant");if(host!=null && !(host instanceof TenantRef))throw SqlServerErrors.database();if(!(req.getAttribute("health.actor") instanceof Actor actor) || !(host instanceof TenantRef tenant) || actor.tenantId()==null || !actor.tenantId().equals(tenant.id()))throw ApiException.forbidden();if(actor.roles()==null)throw SqlServerErrors.database();if(actor.roles().contains("SAD") || actor.roles().contains("SOP") || Collections.disjoint(actor.roles(),roles))throw ApiException.forbidden();var c=SqlServerRequestContexts.from(req,SqlServerContext.Scope.REQUEST);if(!canonical(c.actorId()) || !canonical(c.tenantId()) || c.tokenHash()==null || !c.tokenHash().matches("[a-fA-F0-9]{64}"))throw SqlServerErrors.database();return c;}
 private static void module(HttpServletRequest req,String module){var tenant=(TenantRef)req.getAttribute("health.tenant");if(tenant.modules()==null || !tenant.modules().contains(module))throw new ApiException(403,"MODULE_NOT_INCLUDED","El contrato no incluye este m\u00f3dulo.");}
 private static SqlServerContext writeContext(HttpServletRequest req,String role){var c=authority(req,Set.of(role));var tenant=(TenantRef)req.getAttribute("health.tenant");if(!Set.of("TRIAL","ACTIVE").contains(Objects.toString(tenant.status(),"")))throw new ApiException(403,"SUSPENDED","El cliente conserva sus datos; las operaciones est\u00e1n suspendidas.");module(req,"INVENTORY");return c;}
 public List<Map<String,Object>> lots(HttpServletRequest request){return within(()->{var c=context(request,"INVENTORY",Set.of("ALM","FAR","AUD"));return rows(executor.execute(SqlServerProcedure.INVENTORY_LOTS,c)).stream().map(row->lot(row,c.tenantId())).toList();});}
 public List<Map<String,Object>> transfers(HttpServletRequest request){return within(()->{var c=context(request,"INVENTORY",Set.of("ALM","AUD"));return rows(executor.execute(SqlServerProcedure.INVENTORY_TRANSFERS,c)).stream().map(row->transfer(row,c.tenantId())).toList();});}
 public List<Map<String,Object>> prescriptions(HttpServletRequest request){return within(()->{var c=context(request,"PHARMACY",Set.of("FAR","PRO","AUD"));return rows(executor.execute(SqlServerProcedure.INVENTORY_PRESCRIPTIONS,c)).stream().map(SqlServerInventoryStore::prescription).toList();});}
 public Map<String,Object> lot(HttpServletRequest request,Lot p){return within(()->{
  var c=writeContext(request,"ALM");if(p==null)throw SqlServerErrors.invalid();Checks.id(p.branchId());if(!nonblank(p.name(),160) || !nonblank(p.lot(),100) || !nonblank(p.unit(),30) || p.expiry()==null || p.expiry().getYear()<1 || p.expiry().getYear()>9999)throw SqlServerErrors.invalid();configuredMapper();String generated=Checks.id();var values=rows(executor.execute(SqlServerProcedure.INVENTORY_LOT_CREATE,c,generated,mapper.writeValueAsString(p)));if(values.size()!=1)throw SqlServerErrors.database();var row=lot(values.getFirst(),c.tenantId());if(!generated.equals(row.get("id")) || !p.branchId().equals(row.get("branchId")) || !p.name().equals(row.get("name")) || !p.lot().equals(row.get("lot")) || !p.unit().equals(row.get("unit")) || !p.expiry().toString().equals(row.get("expiry")) || ((BigDecimal)row.get("quantity")).signum()!=0)throw SqlServerErrors.database();return row;
 });}
 public Map<String,Object> move(HttpServletRequest request,Move p,String key){return within(()->{
  boolean dispense=p!=null && "DISPENSE".equals(p.kind());var c=writeContext(request,dispense?"FAR":"ALM");if(p==null || p.kind()==null || !Set.of("RECEIVE","DISPENSE").contains(p.kind()))throw SqlServerErrors.invalid();
  if(dispense && p.prescriptionId()==null)throw ApiException.invalid("Selecciona la prescripci\u00f3n a dispensar.");Checks.id(p.lotId());if(p.patientId()!=null)Checks.id(p.patientId());if(p.prescriptionId()!=null)Checks.id(p.prescriptionId());inputQuantity(p.quantity());String requestKey=Idempotency.key(key);if(dispense)module(request,"PHARMACY");configuredMapper();String json=mapper.writeValueAsString(p),hash=Checks.hash(json),generated=Checks.id();var values=rows(executor.execute(SqlServerProcedure.INVENTORY_MOVE,c,generated,json,requestKey,hash));if(values.size()!=1)throw SqlServerErrors.database();var row=movement(values.getFirst(),c.tenantId());if(!p.lotId().equals(row.get("lotId")) || !p.kind().equals(row.get("kind")) || p.quantity().compareTo((BigDecimal)row.get("quantity"))!=0 || !Objects.equals(p.patientId(),row.get("patientId")) || !Objects.equals(p.prescriptionId(),row.get("prescriptionId")) || !requestKey.equals(row.get("requestKey")) || !hash.equals(row.get("requestHash")) || generated.equals(row.get("id"))&&!c.actorId().equals(row.get("actorId")))throw SqlServerErrors.database();return row;
 });}
 public Map<String,Object> transfer(HttpServletRequest request,Transfer p,String key){return within(()->{
  var c=writeContext(request,"ALM");if(p==null)throw SqlServerErrors.invalid();Checks.id(p.lotId());Checks.id(p.destinationBranchId());inputQuantity(p.quantity());String requestKey=Idempotency.key(key);configuredMapper();String json=mapper.writeValueAsString(p),hash=Checks.hash(json),generated=Checks.id();var row=transferOne(executor.execute(SqlServerProcedure.INVENTORY_TRANSFER_START,c,generated,json,requestKey,hash),c.tenantId());
  if(!p.lotId().equals(row.get("lotId")) || !p.destinationBranchId().equals(row.get("destinationBranchId")) || p.quantity().compareTo((BigDecimal)row.get("quantity"))!=0 || !requestKey.equals(row.get("requestKey")) || !hash.equals(row.get("requestHash")))throw SqlServerErrors.database();
  boolean received="RECEIVED".equals(row.get("status"));if(received?row.get("receivedAt")==null:row.get("receivedAt")!=null)throw SqlServerErrors.database();if(generated.equals(row.get("id")) && received)throw SqlServerErrors.database();return row;
 });}
 public Map<String,Object> receive(HttpServletRequest request,String id){return within(()->{var c=writeContext(request,"ALM");Checks.id(id);var row=transferOne(executor.execute(SqlServerProcedure.INVENTORY_TRANSFER_RECEIVE,c,id),c.tenantId());if(!id.equals(row.get("id")) || !"RECEIVED".equals(row.get("status")) || row.get("receivedAt")==null)throw SqlServerErrors.database();return row;});}
 private static Map<String,Object> transferOne(SqlServerExecutor.Result result,String tenant){var values=rows(result);if(values.size()!=1)throw SqlServerErrors.database();return transfer(values.getFirst(),tenant);}
 private void configuredMapper(){if(mapper==null)throw SqlServerErrors.database();}
 private static boolean nonblank(String value,int max){return value!=null && !value.isBlank() && value.length()<=max;}
 private static void inputQuantity(BigDecimal value){if(value==null || value.signum()<=0)throw SqlServerErrors.invalid();var exact=value.stripTrailingZeros();if(exact.scale()>3 || (long)exact.precision()-exact.scale()>11)throw SqlServerErrors.invalid();}
 private static Map<String,Object> movement(Map<String,Object> row,String tenant){var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","tenantId","lotId","actorId"))out.put(key,id(row,key));if(!tenant.equals(out.get("tenantId")))throw SqlServerErrors.database();String kind=text(row,"kind",8);if(!Set.of("RECEIVE","DISPENSE").contains(kind))throw SqlServerErrors.database();out.put("kind",kind);out.put("quantity",quantity(row,true));out.put("patientId",nullableId(row,"patientId"));out.put("prescriptionId",nullableId(row,"prescriptionId"));out.put("requestKey",text(row,"requestKey",100));String hash=text(row,"requestHash",64);if(!hash.matches("[a-fA-F0-9]{64}"))throw SqlServerErrors.database();out.put("requestHash",hash);out.put("createdAt",time(row,"createdAt",false));return Collections.unmodifiableMap(out);}
 private static String nullableId(Map<String,Object> row,String key){Object value=field(row,key);if(value==null)return null;if(!(value instanceof String id) || !canonical(id))throw SqlServerErrors.database();return id;}
 private static List<Map<String,Object>> rows(SqlServerExecutor.Result result){if(result==null || result.resultSets().size()!=1 || result.resultSets().getFirst().size()>200)throw SqlServerErrors.database();return result.resultSets().getFirst();}
 private static Map<String,Object> lot(Map<String,Object> row,String tenant){var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","tenantId","branchId"))out.put(key,id(row,key));if(!tenant.equals(out.get("tenantId")))throw SqlServerErrors.database();out.put("name",text(row,"name",160));out.put("lot",text(row,"lot",100));out.put("expiry",date(row,"expiry"));out.put("quantity",quantity(row,false));out.put("unit",text(row,"unit",30));return Collections.unmodifiableMap(out);}
 private static Map<String,Object> transfer(Map<String,Object> row,String tenant){var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","tenantId","lotId","destinationBranchId"))out.put(key,id(row,key));if(!tenant.equals(out.get("tenantId")))throw SqlServerErrors.database();out.put("quantity",quantity(row,true));String status=text(row,"status",10);if(!Set.of("IN_TRANSIT","RECEIVED").contains(status))throw SqlServerErrors.database();out.put("status",status);out.put("requestKey",text(row,"requestKey",100));String hash=text(row,"requestHash",64);if(!hash.matches("[a-fA-F0-9]{64}"))throw SqlServerErrors.database();out.put("requestHash",hash);out.put("createdAt",time(row,"createdAt",false));out.put("receivedAt",time(row,"receivedAt",true));return Collections.unmodifiableMap(out);}
 private static Map<String,Object> prescription(Map<String,Object> row){var out=new LinkedHashMap<String,Object>();for(String key:List.of("id","encounterId","patientId","branchId"))out.put(key,id(row,key));out.put("payload",json(field(row,"payload"),Collections.newSetFromMap(new IdentityHashMap<>())));out.put("createdAt",time(row,"createdAt",false));return Collections.unmodifiableMap(out);}
 private static BigDecimal quantity(Map<String,Object> row,boolean positive){if(!(field(row,"quantity") instanceof BigDecimal value) || value.signum()<0 || positive&&value.signum()==0)throw SqlServerErrors.database();BigDecimal exact=value.stripTrailingZeros();if(exact.scale()>3 || (long)exact.precision()-exact.scale()>11)throw SqlServerErrors.database();return value;}
 private static Object field(Map<String,Object> row,String key){if(row==null || !row.containsKey(key))throw SqlServerErrors.database();return row.get(key);}
 private static String text(Map<String,Object> row,String key,int max){if(!(field(row,key) instanceof String value) || value.length()>max)throw SqlServerErrors.database();return value;}
 private static boolean canonical(String value){if(value==null)return false;try{return UUID.fromString(value).toString().equals(value);}catch(IllegalArgumentException invalid){return false;}}
 private static String id(Map<String,Object> row,String key){String value=text(row,key,36);if(!canonical(value))throw SqlServerErrors.database();return value;}
 private static String date(Map<String,Object> row,String key){String value=text(row,key,10);try{LocalDate date=LocalDate.parse(value);if(!value.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}") || date.getYear()<1 || date.getYear()>9999 || !date.toString().equals(value))throw SqlServerErrors.database();}catch(DateTimeException invalid){throw SqlServerErrors.database();}return value;}
 private static String time(Map<String,Object> row,String key,boolean nullable){Object value=field(row,key);if(value==null && nullable)return null;if(!(value instanceof String text))throw SqlServerErrors.database();try{Instant time=Instant.parse(text);if(!text.endsWith("Z") || time.getNano()%1000!=0 || time.isBefore(Instant.parse("0001-01-01T00:00:00Z")) || time.isAfter(Instant.parse("9999-12-31T23:59:59.999999Z")))throw SqlServerErrors.database();}catch(DateTimeException invalid){throw SqlServerErrors.database();}return text;}
 private static Object json(Object value,Set<Object> ancestors){if(value==null || value instanceof String || value instanceof Boolean || value instanceof Byte || value instanceof Short || value instanceof Integer || value instanceof Long || value instanceof BigInteger || value instanceof BigDecimal)return value;if(value instanceof Double n && Double.isFinite(n) || value instanceof Float f && Float.isFinite(f))return value;if(!(value instanceof Map<?,?>) && !(value instanceof List<?>) || !ancestors.add(value))throw SqlServerErrors.database();try{if(value instanceof List<?> list){var copy=new ArrayList<Object>();for(Object item:list)copy.add(json(item,ancestors));return Collections.unmodifiableList(copy);}var copy=new LinkedHashMap<String,Object>();((Map<?,?>)value).forEach((key,item)->{if(!(key instanceof String name))throw SqlServerErrors.database();copy.put(name,json(item,ancestors));});return Collections.unmodifiableMap(copy);}finally{ancestors.remove(value);}}
 @Override public String toString(){return "SqlServerInventoryStore[redacted]";}
}
